{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The aws_instance.web resource does not specify encryption for its Elastic Block Store (EBS) volumes, potentially leaving data stored on those volumes unencrypted."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The aws_instance.web resource does not specify the metadata_options, potentially allowing Instance Metadata Service Version 1 to be enabled, which is less secure than Version 2."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The aws_instance.web resource does not specify an IAM instance profile, meaning it is not attached to an IAM role, potentially limiting its ability to securely access AWS resources."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"web\" {\n  ami                    = \"${var.ami}\"\n  instance_type          = \"t2.micro\"\n  subnet_id              = \"${aws_subnet.public-subnet.id}\"\n  vpc_security_group_ids = [\"${aws_security_group.sgweb.id}\"]\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n  root_block_device {\n    encrypted = true\n  }\n  iam_instance_profile = \"${aws_iam_instance_profile.example.name}\"\n}",
  "fix_summary": "Added metadata_options to disable IMDSv1, enabled encryption on the root_block_device EBS volume, and added an IAM instance profile to the EC2 instance."
}
